#pragma once
#include <string_view>
#include <vector>

// The vanilla direction speed ladders of the third-person character graphs (VanillaLadders.inl, generated by
// tools/gen_vanilla_ladders.py from the Behavior Atlas and checked against the game's own graphs on 11-14: 153 blenders
// equal in clip, animation, weight, playback, mode and triggers). core/LocomotionSplit rebuilds a declared blender from
// its record when another mod changed it, so the result is always vanilla + the declaration.
namespace AnimationInjector::VanillaLadders {

struct Trigger {
    const char* event;
    float time;
    bool relativeToEnd;
};
struct Slot {
    const char* clip;
    const char* animation;
    float weight;
    float playback;
    int mode;   // hkbClipGenerator::PlaybackMode
    int flags;  // hkbClipGenerator flags
    std::vector<Trigger> triggers;
};
struct Ladder {
    const char* graph;    // the graph's root generator name ("Melee_Locomotion_Behavior")
    const char* blender;  // "1HM_ForwardBlend"
    std::vector<Slot> slots;
};

// The record of `blender` in the graph whose root generator is `graph` (names ignoring case), or null.
// 2HW_<Direction>Blend and H2H_<Direction>Blend (made by core/OwnLocomotion, no vanilla blender) give the 2HM and
// the 1HM blender's record with the clip names' prefix read as 2HW_ / H2H_ (animations and everything else as the
// source's).
const Ladder* Find(std::string_view graph, std::string_view blender);

}  // namespace AnimationInjector::VanillaLadders
